// ─── Editing seam (feature item) ──────────────────────────────────────────────

/** What the editing panel receives. A superset of a `renderEditor({ item, onApply, onCancel })` slot. */
export interface CarouselEditorPanelProps {
  item: MediaCarouselItem;
  /**
   * The shared aspect, ready for media-editor's canvas `aspect` and
   * `cropAspects`: a named ratio, `"free"`, or `"W:H"` (0.4.0 — `"original"`
   * arrives resolved to item 1's ratio as `"W:H"`). Breaking in 0.4.0: a custom
   * panel that switched over the five 0.3 values must handle `"W:H"`.
   */
  aspect: Exclude<CarouselAspectRatio, "original">;
  /** `aspect` as width / height (0.4.0); `null` for `"free"`. */
  aspectRatio: number | null;
  labels: Pick<CarouselComposerLabels, "editDone" | "editCancel" | "editSaving" | "editError">;
  /** `CarouselComposerProps.editorProps`, passed through untouched. */
  editorProps?: Readonly<Record<string, unknown>>;
  /** Commit an edit: replaces the item's `url` / `blob` and stores the edit fields. */
  onApply: (id: string, patch: ApplyEditPatch) => void;
  onCancel: () => void;
  /**
   * 0.5.0. Report that the panel is preparing or saving (loading its source,
   * encoding an export). While a panel reports busy the carousel swallows
   * Escape before any dialog sees it, so a host dialog around the carousel does
   * not close mid-preparation. Report `false` when done; unmounting clears it.
   * The shipped editing panel reports its load and its Done export.
   */
  onBusyChange?: (busy: boolean) => void;
}

/**
 * Image editing, injected: `editing={carouselEditing}` from
 * `@/components/carousel-composer/features/editing` (registry item
 * `@ilinxa/carousel-composer-editing`), or your own `{ Panel }`. Without it the
 * preview has no Edit button.
 */
export interface CarouselEditingExtension {
  Panel: ComponentType<CarouselEditorPanelProps>;
}

// ─── Props / handle ───────────────────────────────────────────────────────────

export interface CarouselComposerProps {
  // value
  value?: MediaCarouselItem[];
  defaultValue?: MediaCarouselItem[];
  onChange?: (items: MediaCarouselItem[]) => void;

  // capability dials
  /** Default 10. */
  maxItems?: number;
  /** Default 50. */
  maxFileSizeMb?: number;
  /** Which kinds are accepted. Default `["image", "video"]`. */
  accept?: MediaKind[];
  /**
   * Exact MIME allow-list, also used for the file input's `accept`. Default: any
   * `image/*` / `video/*` (filtered by `accept`). `PLATFORM_SAFE_MIME` refuses WebM.
   */
  acceptMime?: readonly string[];
  /** Refuse videos longer than this, in seconds (read from the file on add). Default: no limit. */
  maxVideoSeconds?: number;
  /** Default `["upload"]`; `"library"` is ignored. */
  sources?: MediaCarouselSource[];
  /**
   * The shared frame aspect of every item (preview, rail thumbs, edit, reported
   * crop). `"auto"` = the nearest of `aspectOptions` (named / `"W:H"` entries;
   * without options the four standard ratios) to item 1's ratio, 1:1 until it
   * is known. 0.4.0: controlled when set — a pick in the aspect switch calls
   * `onAspectChange` and waits for the new value.
   */
  aspect?: CarouselAspectRatio | "auto";
  /** 0.4.0. Starting aspect when `aspect` is not set. Default `"auto"`. */
  defaultAspect?: CarouselAspectRatio | "auto";
  /** 0.4.0. Fires when the user picks an option in the aspect switch. */
  onAspectChange?: (aspect: CarouselAspectRatio) => void;
  /**
   * 0.4.0. Shows an aspect switch on the main preview while item 1 is selected
   * and nothing is being edited (Instagram: the first photo decides). At least
   * two valid entries; invalid ones are dropped (one dev warning). Without it
   * there is no switch.
   */
  aspectOptions?: CarouselAspectRatio[];
  /**
   * 0.5.0. Lets the author drag an image inside the shared frame (Instagram):
   * pointer drag or arrow keys on the main preview move the item's
   * `cropOffset`. Images whose ratio differs from the shared aspect only; no
   * zoom. Default false (every image centred, as before).
   */
  enablePan?: boolean;
  /** 0.5.0. Fires when a pan gesture (or arrow key) settles on a new `cropOffset`. */
  onCropOffsetChange?: (id: string, offset: CarouselCropOffset) => void;

  // reorder
  /**
   * 0.5.0. Adds a "move earlier / move later" button pair to each rail thumb —
   * shown while the thumb is hovered or one of the pair has focus (Tab reaches
   * it), so the rail at rest looks as
   * before — as a keyboard, pointer, assistive-technology and test path that
   * needs no drag or layout. Default false.
   */
  reorderButtons?: boolean;

  // editing (feature item)
  /** Image editing add-on. Without it there is no Edit button and `openEditor` does nothing (one dev warning). */
  editing?: CarouselEditingExtension;
  /** Which items can be edited. Default: images. A video is never editable (its output is the original file). */
  canEditItem?: (item: MediaCarouselItem) => boolean;
  /**
   * Passed to the editing panel untouched — with the add-on, media-editor props
   * (`enabledTools`, `stickers`, `fonts`, `colorPresets`, `filterPresets`, `labels`);
   * type it with the add-on's `CarouselEditorProps`. Ignored without `editing` (one dev warning).
   */
  editorProps?: Readonly<Record<string, unknown>>;

  // alt text
  /**
   * Show an alt-text field (with its counter) for the selected item. Default
   * false. `true` / `"images"`: images only. 0.5.0: `"all"` describes videos
   * too; a function decides per item.
   */
  enableAltText?: boolean | "images" | "all" | ((item: MediaCarouselItem) => boolean);
  /** Default 200. */
  maxAltLength?: number;

  // upload status
  /** Shows a Retry on an item with `status: "error"`. */
  onRetry?: (item: MediaCarouselItem) => void;

  // video
  /** Seconds into a video to grab its poster frame; `false` = no poster. Default 0.5. */
  posterAt?: number | false;
  /** Formats a video's duration badge. Default `m:ss` (`h:mm:ss` past an hour), digits in `locale`. */
  formatDuration?: (seconds: number) => string;
  /** BCP 47 tag for the default duration format. Default `"en"`. */
  locale?: string;
  /** Text direction (the rail mirrors in RTL). Default: read from the element after mount. */
  dir?: "ltr" | "rtl";

  labels?: CarouselComposerLabelsInput;
  className?: string;
  /**
   * Revoke object URLs this component created when it unmounts. Default true.
   * Set false ONLY when a host preserves the live items across remounts and
   * takes over final cleanup (e.g. content-composer's carousel cache).
   */
  revokeOnUnmount?: boolean;

  // events
  onItemAdd?: (item: MediaCarouselItem) => void;
  onItemRemove?: (id: string) => void;
  onReorder?: (items: MediaCarouselItem[]) => void;
  /**
   * 0.5.0. Fires for a one-step move (the `reorderButtons` pair or
   * `handle.moveItem`): `delta` is the change in position (−1 earlier, +1 later),
   * after the move. `onReorder` fires too.
   */
  onMove?: (id: string, delta: number) => void;
  onSelect?: (id: string | null) => void;
  /**
   * 0.5.0. Fires `true` when an edit panel opens and `false` when it closes.
   * Use it to keep a host dialog open while editing (the carousel already
   * swallows Escape while a panel reports busy).
   */
  onEditingChange?: (editing: boolean) => void;
  onEditOpen?: (id: string) => void;
  onEditApply?: (item: MediaCarouselItem) => void;
  onEditCancel?: (id: string) => void;
  onValidationError?: (error: MediaCarouselError) => void;
  onMaxItemsExceeded?: (attempted: number, max: number) => void;
}

export interface CarouselComposerHandle {
  getItems: () => MediaCarouselItem[];
  /**
   * Resolves a copy of the COMMITTED ordered items (edits already flattened). An
   * open, unapplied edit is not included — gate publish while editing. 0.4.0:
   * each image of known size carries `crop` for the shared aspect.
   */
  export: () => Promise<MediaCarouselItem[]>;
  /**
   * 0.4.0. The shared aspect as resolved now (`"auto"` and `"original"` turned
   * into a value) and its width / height (`null` for `"free"`).
   */
  getAspect: () => { aspect: CarouselAspectRatio; ratio: number | null };
  /** Same path as the dropzone, with the current props. Resolves once the files are read and added. */
  addFiles: (files: File[] | FileList) => Promise<void>;
  removeItem: (id: string) => void;
  /**
   * 0.5.0. Move an item by `delta` positions (negative = earlier), clamped to
   * the list. Same path as the `reorderButtons` pair: fires `onReorder` and
   * `onMove`; ignored while an edit is open.
   */
  moveItem: (id: string, delta: number) => void;
  /** Patch an item (upload `status` / `progress` / `error`, the uploaded `url`, `alt`…). */
  updateItem: (id: string, patch: MediaCarouselItemPatch) => void;
  select: (id: string | null) => void;
  /** Open the editor for an item. Needs `editing`; videos and items `canEditItem` refuses are ignored (dev warning). */
  openEditor: (id: string) => void;
  /** Revoke all owned object URLs and clear the items. (Unmount revokes owned URLs too, unless `revokeOnUnmount={false}`.) */
  reset: () => void;
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type {
  ApplyEditPatch,
  MediaCarouselItem,
  MediaCarouselItemPatch,
} from "../types";
import { useControllableState } from "./use-controllable-state";
import { useWarnOnce } from "./use-warn-once";

export interface CarouselStateCallbacks {
  onItemAdd?: (item: MediaCarouselItem) => void;
  onItemRemove?: (id: string) => void;
  onReorder?: (items: MediaCarouselItem[]) => void;
  onSelect?: (id: string | null) => void;
  onEditOpen?: (id: string) => void;
  onEditApply?: (item: MediaCarouselItem) => void;
  onEditCancel?: (id: string) => void;
  onMaxItemsExceeded?: (attempted: number, max: number) => void;
}

export interface UseCarouselStateOptions extends CarouselStateCallbacks {
  value?: MediaCarouselItem[];
  defaultValue?: MediaCarouselItem[];
  onChange?: (items: MediaCarouselItem[]) => void;
  maxItems: number;
  /**
   * Revoke owned object URLs when the component unmounts. Default true. A host
   * that persists the live items across remounts (e.g. content-composer's
   * carousel cache) sets this false and owns the final cleanup itself.
   */
  revokeOnUnmount?: boolean;
  /**
   * Whether an item may be edited. Images only by default; `openEditor` ignores
   * (with a dev warning) any item this refuses.
   */
  canEdit?: (item: MediaCarouselItem) => boolean;
}

export type { ApplyEditPatch };

export interface UseCarouselStateResult {
  items: MediaCarouselItem[];
  selectedId: string | null;
  editingId: string | null;
  selectedItem: MediaCarouselItem | null;
  editingItem: MediaCarouselItem | null;
  addItems: (next: MediaCarouselItem[]) => void;
  removeItem: (id: string) => void;
  reorder: (next: MediaCarouselItem[]) => void;
  select: (id: string | null) => void;
  openEditor: (id: string) => void;
  cancelEdit: () => void;
  applyEdit: (id: string, patch: ApplyEditPatch) => void;
  /** Merge a patch into one item (upload status, alt…). No-op for an unknown id. */
  updateItem: (id: string, patch: MediaCarouselItemPatch) => void;
  reset: () => void;
  /** The latest items, including changes made earlier in the same tick. Stable identity. */
  getItems: () => MediaCarouselItem[];
}

/** Only object URLs we created are ours to revoke; remote/consumer URLs aren't. */
function isOwnable(url: string): boolean {
  return url.startsWith("blob:");
}

/**
 * Owns the carousel model: a controllable `items` array (value/defaultValue/
 * onChange) plus internal `selectedId` / `editingId`, and the object-URL
 * lifecycle. `itemsRef` is updated SYNCHRONOUSLY inside every mutator (not via an
 * effect) so async/batched intakes can't read a stale base. An orphan-revoke
 * effect catches URLs dropped by any path — including a wholesale controlled
 * `value` swap (e.g. the host's `loadValue`) that bypasses removeItem.
 */
export function useCarouselState(
  opts: UseCarouselStateOptions,
): UseCarouselStateResult {
  const { maxItems, revokeOnUnmount = true } = opts;

  const [items, setItemsRaw] = useControllableState<MediaCarouselItem[]>({
    value: opts.value,
    defaultValue: opts.defaultValue ?? [],
    onChange: opts.onChange,
    componentName: "CarouselComposer",
    valuePropName: "value",
  });
  const [rawSelectedId, setSelectedId] = useState<string | null>(
    opts.value?.[0]?.id ?? opts.defaultValue?.[0]?.id ?? null,
  );
  const [editingId, setEditingId] = useState<string | null>(null);

  const selectedId =
    rawSelectedId != null && items.some((it) => it.id === rawSelectedId)
      ? rawSelectedId
      : (items[0]?.id ?? null);

  const cbRef = useRef<CarouselStateCallbacks & Pick<UseCarouselStateOptions, "canEdit">>(opts);
  useEffect(() => {
    cbRef.current = opts;
  });

  // itemsRef tracks committed render state; mutators below ALSO write it
  // synchronously so a second mutation in the same tick reads the latest base.
  const itemsRef = useRef(items);
  const selectedIdRef = useRef(selectedId);
  const editingIdRef = useRef(editingId);
  useEffect(() => {
    itemsRef.current = items;
    selectedIdRef.current = selectedId;
    editingIdRef.current = editingId;
  });
  const warnOnce = useWarnOnce();
  const getItems = useCallback(() => itemsRef.current, []);

  /** Synchronous-ref write + state set, so chained mutators compose correctly. */
  const setItems = useCallback(
    (next: MediaCarouselItem[]) => {
      itemsRef.current = next;
      setItemsRaw(next);
    },
    [setItemsRaw],
  );

  // Object-URL ownership. A URL is revoked by the orphan effect once it has been
  // committed in `items` at least once and then dropped. A URL the host has not
  // rendered yet (a controlled host that echoes `onChange` late) is never revoked
  // by an unrelated commit.
  const ownedUrls = useRef<Set<string>>(new Set());
  const seenUrls = useRef<Set<string>>(new Set());

  useEffect(() => {
    const present = new Set<string>();
    items.forEach((it) => {
      present.add(it.url);
      if (it.posterUrl) present.add(it.posterUrl);
    });
    present.forEach((u) => seenUrls.current.add(u));
    ownedUrls.current.forEach((u) => {
      if (!present.has(u) && seenUrls.current.has(u)) {
        URL.revokeObjectURL(u);
        ownedUrls.current.delete(u);
        seenUrls.current.delete(u);
      }
    });
  }, [items]);

  // Read at unmount time, so flipping the flag at runtime revokes nothing.
  const revokeOnUnmountRef = useRef(revokeOnUnmount);
  useEffect(() => {
    revokeOnUnmountRef.current = revokeOnUnmount;
  });
  useEffect(() => {
    const owned = ownedUrls.current;
    return () => {
      if (!revokeOnUnmountRef.current) return;
      owned.forEach((u) => URL.revokeObjectURL(u));
      owned.clear();
    };
  }, []);

  const addItems = useCallback(
    (incoming: MediaCarouselItem[]) => {
      if (incoming.length === 0) return;
      // Cap synchronously against the latest items (race-safe).
      const room = Math.max(0, maxItems - itemsRef.current.length);
      const toAdd = incoming.slice(0, room);
      const dropped = incoming.slice(room);
      // Revoke object URLs of items we won't keep (intake created them).
      dropped.forEach((it) => {
        if (isOwnable(it.url)) URL.revokeObjectURL(it.url);
        if (it.posterUrl && isOwnable(it.posterUrl)) {
          URL.revokeObjectURL(it.posterUrl);
        }
      });
      if (toAdd.length > 0) {
        toAdd.forEach((it) => {
          if (isOwnable(it.url)) ownedUrls.current.add(it.url);
          if (it.posterUrl && isOwnable(it.posterUrl)) {
            ownedUrls.current.add(it.posterUrl);
          }
        });
        setItems([...itemsRef.current, ...toAdd]);
        toAdd.forEach((it) => cbRef.current.onItemAdd?.(it));
      }
      if (dropped.length > 0) {
        cbRef.current.onMaxItemsExceeded?.(
          itemsRef.current.length + dropped.length,
          maxItems,
        );
      }
    },
    [maxItems, setItems],
  );

  const removeItem = useCallback(
    (id: string) => {
      const cur = itemsRef.current;
      const idx = cur.findIndex((it) => it.id === id);
      if (idx < 0) return;
      const next = cur.filter((it) => it.id !== id);
      setItems(next);
      cbRef.current.onItemRemove?.(id);
      if (selectedIdRef.current === id) {
        const neighbor = next[Math.min(idx, next.length - 1)] ?? null;
        const nid = neighbor?.id ?? null;
        setSelectedId(nid);
        cbRef.current.onSelect?.(nid);
      }
      if (editingIdRef.current === id) {
        editingIdRef.current = null;
        setEditingId(null);
        cbRef.current.onEditCancel?.(id);
      }
    },
    [setItems],
  );

  const reorder = useCallback(
    (next: MediaCarouselItem[]) => {
      setItems(next);
      cbRef.current.onReorder?.(next);
    },
    [setItems],
  );

  const select = useCallback((id: string | null) => {
    setSelectedId(id);
    cbRef.current.onSelect?.(id);
  }, []);

  const openEditor = useCallback((id: string) => {
    // Only images are editable — a video must never reach the editor, whose
    // export() would re-encode it.
    const target = itemsRef.current.find((it) => it.id === id);
    if (!target) return;
    if (target.kind !== "image") {
      if (process.env.NODE_ENV !== "production") {
        console.warn(
          `[CarouselComposer] openEditor("${id}") ignored: item is a ${target.kind}; only image items can be edited.`,
        );
      }
      return;
    }
    if (cbRef.current.canEdit?.(target) === false) {
      if (process.env.NODE_ENV !== "production") {
        console.warn(
          `[CarouselComposer] openEditor("${id}") ignored: canEditItem refused this item.`,
        );
      }
      return;
    }
    // Written now, not in a later effect: a Panel may call onCancel in its mount effect.
    editingIdRef.current = id;
    setSelectedId(id);
    setEditingId(id);
    cbRef.current.onEditOpen?.(id);
  }, []);

  const cancelEdit = useCallback(() => {
    const id = editingIdRef.current;
    if (id == null) return;
    editingIdRef.current = null;
    setEditingId(null);
    cbRef.current.onEditCancel?.(id);
  }, []);

  const applyEdit = useCallback(
    (id: string, patch: ApplyEditPatch) => {
      const cur = itemsRef.current;
      const idx = cur.findIndex((it) => it.id === id);
      if (editingIdRef.current !== id || idx < 0) {
        // Not the open edit (foreign id, unknown id, or a repeat after it closed).
        // A blob URL the panel minted for it would leak, so release it.
        const inUse = cur.some(
          (it) => it.url === patch.url || it.posterUrl === patch.url,
        );
        if (
          isOwnable(patch.url) &&
          !ownedUrls.current.has(patch.url) &&
          !inUse
        ) {
          URL.revokeObjectURL(patch.url);
        }
        warnOnce(
          "applyEdit-not-editing",
          `[CarouselComposer] onApply("${id}") ignored: that item is not the one being edited.`,
        );
        return;
      }
      const prev = cur[idx];
      if (isOwnable(patch.url)) ownedUrls.current.add(patch.url);
      // The edited media is not the uploaded one: drop the upload state. The host
      // re-uploads from onEditApply. The old URL is released by the orphan effect.
      const updated: MediaCarouselItem = {
        ...prev,
        url: patch.url,
        blob: patch.blob ?? prev.blob,
        editorState: patch.editorState ?? prev.editorState,
        sourceBlob: patch.sourceBlob ?? prev.sourceBlob,
        exportMeta: patch.exportMeta ?? prev.exportMeta,
        width: patch.width ?? prev.width,
        height: patch.height ?? prev.height,
      };
      // The edit bakes the frame into the image: a pan offset no longer applies.
      delete updated.cropOffset;
      delete updated.status;
      delete updated.progress;
      delete updated.error;
      setItems(cur.map((it, i) => (i === idx ? updated : it)));
      editingIdRef.current = null;
      setEditingId(null);
      cbRef.current.onEditApply?.(updated);
    },
    [setItems, warnOnce],
  );

  const updateItem = useCallback(
    (id: string, patch: MediaCarouselItemPatch) => {
      const cur = itemsRef.current;
      const idx = cur.findIndex((it) => it.id === id);
      if (idx < 0) return;
      const updated: MediaCarouselItem = { ...cur[idx], ...patch };
      // A different image (new pixel size) has its own frame: the old pan offset does not
      // carry over. A url-only patch (an upload of the same image) keeps it.
      const prevItem = cur[idx];
      const sizeChanged =
        (patch.width !== undefined && patch.width !== prevItem.width) ||
        (patch.height !== undefined && patch.height !== prevItem.height);
      if (sizeChanged && !("cropOffset" in patch)) {
        delete updated.cropOffset;
      }
      // A new blob: URL from the host is the host's to revoke; the old owned one
      // is released by the orphan effect once it leaves `items`.
      setItems(cur.map((it, i) => (i === idx ? updated : it)));
    },
    [setItems],
  );

  const reset = useCallback(() => {
    ownedUrls.current.forEach((u) => URL.revokeObjectURL(u));
    ownedUrls.current.clear();
    setItems([]);
    setSelectedId(null);
    editingIdRef.current = null;
    setEditingId(null);
  }, [setItems]);

  const selectedItem = items.find((it) => it.id === selectedId) ?? null;
  const editingItem = items.find((it) => it.id === editingId) ?? null;

  return {
    items,
    selectedId,
    editingId,
    selectedItem,
    editingItem,
    addItems,
    removeItem,
    reorder,
    select,
    openEditor,
    cancelEdit,
    applyEdit,
    updateItem,
    reset,
    getItems,
  };
}

import { useCallback, useEffect, useRef, useState } from "react";

interface UseControllableStateOpts<T> {
  /** Controlled value. When provided, state is fully controlled by parent. */
  value?: T;
  /** Initial value for uncontrolled mode. */
  defaultValue: T;
  /** Fires on every state change (both modes). */
  onChange?: (next: T) => void;
  /** Component name used in dev warnings. */
  componentName: string;
  /** Prop name used in dev warnings (e.g., `"value"`). */
  valuePropName: string;
}

/**
 * Controlled+uncontrolled state-machine helper. Sealed local copy of the
 * library's standard generic (navigation/account-switcher + code-block) —
 * registry components can't share an app-level util beyond `@/lib/utils`, so
 * each procomp seals its own copy.
 *
 *   - Locks the controlled/uncontrolled mode based on the FIRST render's
 *     `value` and dev-warns when consumers flip modes mid-life.
 *   - Dev-warns when controlled mode is used without an `onChange` handler.
 *
 * Both warns tree-shake out of prod bundles.
 *
 * Internal helper — not exported from the procomp's public API.
 */
export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
  componentName,
  valuePropName,
}: UseControllableStateOpts<T>): readonly [T, (next: T) => void] {
  const [internal, setInternal] = useState<T>(defaultValue);
  const isControlled = value !== undefined;
  const onChangeRef = useRef(onChange);
  useEffect(() => {
    onChangeRef.current = onChange;
  });

  const wasControlledRef = useRef(isControlled);
  useEffect(() => {
    if (process.env.NODE_ENV === "production") return;
    if (wasControlledRef.current !== isControlled) {
      console.warn(
        `[${componentName}] \`${valuePropName}\` switched from ${
          wasControlledRef.current ? "controlled" : "uncontrolled"
        } to ${
          isControlled ? "controlled" : "uncontrolled"
        } mode. Components should not switch modes mid-life; pick one at mount.`,
      );
      wasControlledRef.current = isControlled;
    }
  }, [isControlled, componentName, valuePropName]);

  useEffect(() => {
    if (process.env.NODE_ENV === "production") return;
    if (isControlled && !onChangeRef.current) {
      const capitalized =
        valuePropName.charAt(0).toUpperCase() + valuePropName.slice(1);
      console.warn(
        `[${componentName}] \`${valuePropName}\` is controlled but no onChange handler was provided. ` +
          `State will appear frozen. Pass \`on${capitalized}Change\` ` +
          `(or use the uncontrolled variant by passing \`default${capitalized}\` instead).`,
      );
    }
  }, [isControlled, componentName, valuePropName]);

  const current = isControlled ? (value as T) : internal;

  const set = useCallback(
    (next: T) => {
      if (!isControlled) setInternal(next);
      onChangeRef.current?.(next);
    },
    [isControlled],
  );

  return [current, set] as const;
}

"use client";

import { useEffect, useLayoutEffect, useState } from "react";

const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export type Direction = "ltr" | "rtl";

/**
 * Resolves text direction (consumer contract C4 / R6): the `dir` prop wins; otherwise the
 * element's direction, read after mount — the computed `direction`, or the nearest explicit
 * non-`auto` `[dir]` ancestor (jsdom has no UA stylesheet for `dir`); otherwise `"ltr"`.
 *
 * The server render and the first client render both return the prop or `"ltr"`, so markup
 * must not depend on the resolved value before mount. Key handling, swipe, carousel and
 * transition logic may. A later direction change is not observed — pass `dir` if the app
 * switches direction at runtime without remounting.
 *
 * Directional props take `"start" | "end"`; physical values stay only as deprecated aliases.
 * Copy into a component's `hooks/`. Canonical copy: `_template/_snippets/` (tests next to it).
 */
export function useDirection(
  ref: React.RefObject<HTMLElement | null>,
  dirProp?: Direction,
): Direction {
  const [resolved, setResolved] = useState<Direction>("ltr");
  useIsoLayoutEffect(() => {
    if (dirProp) return;
    const el = ref.current;
    if (!el) return;
    const explicit = el.closest('[dir]:not([dir="auto"])')?.getAttribute("dir")?.toLowerCase();
    const rtl = getComputedStyle(el).direction === "rtl" || explicit === "rtl";
    setResolved(rtl ? "rtl" : "ltr");
  }, [dirProp, ref]);
  return dirProp ?? resolved;
}

"use client";

import { useCallback, useEffect } from "react";
import type { CarouselComposerProps, CarouselEditingExtension } from "../types";
import { useWarnOnce } from "./use-warn-once";

/**
 * Editing injection seam. The base never imports the editing feature; a host
 * passes `editing={carouselEditing}` (from `features/editing`) or its own
 * `{ Panel }`. This hook resolves the prop and warns, once per instance, about
 * `editorProps` that nothing will receive.
 */
export function useEditingExtension(
  props: Pick<CarouselComposerProps, "editing" | "editorProps">,
): {
  editing: CarouselEditingExtension | undefined;
  /** Warns once that `openEditor` was called with no `editing` wired. */
  warnOpenWithoutEditing: (id: string) => void;
} {
  const { editing, editorProps } = props;
  const warnOnce = useWarnOnce();

  useEffect(() => {
    if (editing || editorProps === undefined) return;
    warnOnce(
      "editorProps-without-editing",
      "[CarouselComposer] `editorProps` was passed without `editing`, so it is ignored. Pass `editing={carouselEditing}` from the editing add-on.",
    );
  }, [editing, editorProps, warnOnce]);

  const warnOpenWithoutEditing = useCallback(
    (id: string) =>
      warnOnce(
        "openEditor-without-editing",
        `[CarouselComposer] openEditor("${id}") ignored: no \`editing\` extension is wired. Pass \`editing={carouselEditing}\` from the editing add-on.`,
      ),
    [warnOnce],
  );

  return { editing, warnOpenWithoutEditing };
}

"use client";

import { useCallback, useState } from "react";

/**
 * A development-only `console.warn` that fires once per key per instance. Call it from
 * effects or handlers, never during render. A no-op in production.
 */
export function useWarnOnce(): (key: string, message: string) => void {
  const [seen] = useState(() => new Set<string>());
  return useCallback(
    (key: string, message: string) => {
      if (process.env.NODE_ENV === "production" || seen.has(key)) return;
      seen.add(key);
      console.warn(message);
    },
    [seen],
  );
}

import type { CarouselAspectRatio, CarouselCropRect, MediaCarouselItem } from "../types";

/** An aspect with `"auto"` and `"original"` already turned into a concrete value. */
export type ResolvedAspect = Exclude<CarouselAspectRatio, "original">;

export interface AspectResolution {
  /** Named ratio, `"free"` or `"W:H"`; never `"auto"` / `"original"`. */
  aspect: ResolvedAspect;
  /** `aspect` as width / height; `null` for `"free"`. */
  ratio: number | null;
  /** The setting was an invalid `"W:H"` and fell back to `"1:1"`. */
  invalid: boolean;
}

const STANDARD: ResolvedAspect[] = ["9:16", "4:5", "1:1", "16:9"];

function parsePart(part: string | undefined): number | null {
  if (part === undefined || part === "" || part !== part.trim()) return null;
  const n = Number(part);
  return Number.isFinite(n) && n > 0 ? n : null;
}

/** `"W:H"` → `[w, h]`; same grammar as media-editor's crop aspect (no whitespace in a part). */
function parseParts(value: string): [number, number] | null {
  const parts = value.split(":");
  if (parts.length !== 2) return null;
  const w = parsePart(parts[0]);
  const h = parsePart(parts[1]);
  if (w === null || h === null) return null;
  const ratio = w / h;
  return Number.isFinite(ratio) && ratio > 0 ? [w, h] : null;
}

/** `"W:H"` → width / height; `null` for anything that is not two finite positive numbers. */
export function parseRatio(value: string): number | null {
  const parts = parseParts(value);
  return parts ? parts[0] / parts[1] : null;
}

/** A valid `"W:H"` rewritten from its parsed numbers; `null` when it is not a ratio. */
function normaliseRatio(value: string): string | null {
  const parts = parseParts(value);
  return parts ? `${parts[0]}:${parts[1]}` : null;
}

/** True for a value the shared aspect can take (`"auto"` excluded: it is a setting, not an option). */
export function isValidAspect(value: string): value is CarouselAspectRatio {
  return value === "free" || value === "original" || parseRatio(value) !== null;
}

function itemRatio(first: MediaCarouselItem | undefined): number | null {
  if (!first?.width || !first?.height) return null;
  return first.width / first.height;
}

/**
 * Resolve the carousel's shared aspect. An explicit value wins; `"auto"` is the
 * nearest of `options` (named / `"W:H"` entries, else the four standard ratios) to
 * item 1's ratio, `"1:1"` until it is known; `"original"` is item 1's own ratio as
 * `"W:H"` (1:1 until known); `"free"` keeps each item as it is (no crop, 1:1 frame).
 */
export function resolveAspect(
  items: MediaCarouselItem[],
  setting: CarouselAspectRatio | "auto",
  options?: readonly CarouselAspectRatio[],
): AspectResolution {
  if (setting === "free") return { aspect: "free", ratio: null, invalid: false };
  if (setting === "original") {
    const w = items[0]?.width;
    const h = items[0]?.height;
    if (!w || !h) return { aspect: "1:1", ratio: 1, invalid: false };
    return { aspect: `${w}:${h}` as ResolvedAspect, ratio: w / h, invalid: false };
  }
  if (setting === "auto") {
    const r = itemRatio(items[0]);
    if (r === null) return { aspect: "1:1", ratio: 1, invalid: false };
    const named = (options ?? []).filter(
      (o): o is ResolvedAspect => o !== "free" && o !== "original" && parseRatio(o) !== null,
    );
    const candidates = named.length > 0 ? named : STANDARD;
    let best = candidates[0];
    let bestDiff = Infinity;
    for (const cand of candidates) {
      const diff = Math.abs((parseRatio(cand) as number) - r);
      if (diff < bestDiff) {
        bestDiff = diff;
        best = cand;
      }
    }
    return { aspect: best, ratio: parseRatio(best), invalid: false };
  }
  const ratio = parseRatio(setting);
  const normal = normaliseRatio(setting);
  if (ratio === null || normal === null) return { aspect: "1:1", ratio: 1, invalid: true };
  return { aspect: normal as ResolvedAspect, ratio, invalid: false };
}

/**
 * CSS `aspect-ratio` value for a frame. `"free"` (and an unresolved `"original"`)
 * falls back to a 1:1 frame so the rail + main preview keep a consistent footprint.
 */
export function aspectToCss(aspect: CarouselAspectRatio): string {
  if (aspect === "free" || aspect === "original") return "1 / 1";
  const parts = parseParts(aspect);
  return parts ? `${parts[0]} / ${parts[1]}` : "1 / 1";
}

const THUMB_BOX_W = 7.5;
const THUMB_BOX_H = 4;
const THUMB_MIN_W = 2;

/** Width of a rail thumb (rem): the exact ratio inside a 7.5 x 4 rem box (min 2 rem wide). */
export function thumbWidthRem(ratio: number | null): number {
  const r = ratio ?? 1;
  return Math.max(THUMB_MIN_W, Math.min(THUMB_BOX_W, THUMB_BOX_H * r));
}

/** Height of a rail thumb (rem): 4 up to the box's own ratio, `width / ratio` for wider ones. */
export function thumbHeightRem(ratio: number | null): number {
  const r = ratio ?? 1;
  if (THUMB_BOX_H * r <= THUMB_BOX_W) return THUMB_BOX_H;
  return THUMB_BOX_W / r;
}

/**
 * The largest centred rectangle of `ratio` (width / height) inside `width` × `height`,
 * in integer pixels. The full rectangle when the ratio already matches within rounding.
 */
export function centredCropRect(width: number, height: number, ratio: number): CarouselCropRect {
  return offsetCropRect(width, height, ratio);
}

/** A cropOffset axis clamped to [0, 1]; missing / non-finite = centred. */
export function clampOffset(n: number | undefined): number {
  if (typeof n !== "number" || !Number.isFinite(n)) return 0.5;
  return Math.min(1, Math.max(0, n));
}

/**
 * The same rectangle as `centredCropRect`, positioned by a focal point (`ox` / `oy`
 * from 0 to 1 over the overflow; 0.5 = centred). The ONE maths for the shown region
 * (`object-position`) and `export()`'s `crop`.
 */
export function offsetCropRect(
  width: number,
  height: number,
  ratio: number,
  offset?: { x: number; y: number },
): CarouselCropRect {
  const full: CarouselCropRect = { x: 0, y: 0, width, height };
  if (!(width > 0) || !(height > 0) || !(ratio > 0) || !Number.isFinite(ratio)) return full;
  // Relative error, so a tiny image (2 x 1 at ratio 1) is not read as "already matching".
  if (Math.abs(width / height - ratio) / ratio < 0.002) return full;
  let w = width;
  let h = height;
  if (width / height > ratio) w = Math.min(width, Math.max(1, Math.round(height * ratio)));
  else h = Math.min(height, Math.max(1, Math.round(width / ratio)));
  const ox = clampOffset(offset?.x);
  const oy = clampOffset(offset?.y);
  return { x: Math.floor((width - w) * ox), y: Math.floor((height - h) * oy), width: w, height: h };
}

// Formatters are pure, so one per locale is shared by every call.
const cache = new Map<string, Intl.NumberFormat>();

function build(locale: string): Intl.NumberFormat {
  return new Intl.NumberFormat(locale, { useGrouping: false, maximumFractionDigits: 4 });
}

function formatterFor(locale: string): Intl.NumberFormat {
  const hit = cache.get(locale);
  if (hit) return hit;
  let made: Intl.NumberFormat;
  try {
    made = build(locale);
  } catch {
    // An invalid tag such as "tr_TR" throws a RangeError; read it as English.
    made = cache.get("en") ?? build("en");
    cache.set("en", made);
  }
  cache.set(locale, made);
  return made;
}

/**
 * Formats a number with digits from `locale`, ungrouped (a ratio such as `1920:1080`
 * must not read `1,920:1,080`) and at most four fraction digits. An invalid `locale` reads as `"en"`.
 */
export function formatNumber(n: number, locale = "en"): string {
  return formatterFor(locale).format(n);
}

import type { MediaCarouselSource } from "../types";

/**
 * `"library"` is declared for forward-compat (pick from existing backend media)
 * but is not implemented — clamp it out so a config that lists it
 * stays valid with no crash and no cosmetic leak (mirrors content-composer's
 * media-source clamp). Always resolves to a non-empty source list.
 */
export function clampSources(
  sources: MediaCarouselSource[] | undefined,
): MediaCarouselSource[] {
  const base = sources && sources.length > 0 ? sources : ["upload"];
  const clamped = base.filter((s) => s === "upload");
  return clamped.length > 0 ? clamped : ["upload"];
}

import type {
  CarouselComposerErrorLabels,
  MediaCarouselError,
  MediaCarouselItem,
  MediaKind,
} from "../types";
import { grabPoster, probeVideo, releaseVideo } from "./poster";
import { validateMediaFile } from "./validate-media-file";

// Per-module-load random prefix so the counter fallback can't collide with ids
// reconstructed from a prior draft after a navigation re-evaluates the module.
const ID_PREFIX = `mci-${Math.floor(Math.random() * 1e9).toString(36)}`;
let idCounter = 0;
function nextId(): string {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    return crypto.randomUUID();
  }
  return `${ID_PREFIX}-${(idCounter++).toString(36)}`;
}

function readImageDims(url: string): Promise<{ width: number; height: number }> {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () =>
      resolve({ width: img.naturalWidth, height: img.naturalHeight });
    img.onerror = () => resolve({ width: 0, height: 0 });
    img.src = url;
  });
}

export interface FilesToItemsOptions {
  accept: MediaKind[];
  acceptMime?: readonly string[];
  maxFileSizeMb: number;
  /** Refuse videos longer than this many seconds. */
  maxVideoSeconds?: number;
  /** Seconds into a video for its poster frame; `false` = none. Default 0.5. */
  posterAt?: number | false;
  errors: CarouselComposerErrorLabels;
}

export interface FilesToItemsResult {
  items: MediaCarouselItem[];
  errors: MediaCarouselError[];
}

/**
 * Validate + ingest dropped/picked files into `MediaCarouselItem`s. Creates
 * object URLs and reads natural dimensions (async) so the resolved aspect is
 * correct on first paint. The `maxItems` cap is enforced downstream in the
 * state hook (`addItems`), synchronously against the latest items — so two rapid
 * drops can't each compute room against a stale count.
 */
export async function filesToItems(
  fileList: File[] | FileList,
  opts: FilesToItemsOptions,
): Promise<FilesToItemsResult> {
  const files = Array.from(fileList);
  const errors: MediaCarouselError[] = [];
  const accepted: File[] = [];

  for (const file of files) {
    const err = validateMediaFile(file, {
      maxFileSizeMb: opts.maxFileSizeMb,
      accept: opts.accept,
      acceptMime: opts.acceptMime,
      errors: opts.errors,
    });
    if (err) {
      errors.push(err);
      continue;
    }
    accepted.push(file);
  }

  const posterAt = opts.posterAt === undefined ? 0.5 : opts.posterAt;

  const built = await Promise.all(
    accepted.map(
      async (
        file,
      ): Promise<{ item: MediaCarouselItem } | { error: MediaCarouselError }> => {
        const kind: MediaKind = file.type.startsWith("video/")
          ? "video"
          : "image";
        const url = URL.createObjectURL(file);
        if (kind === "image") {
          const dims = await readImageDims(url);
          return {
            item: {
              id: nextId(),
              kind,
              url,
              blob: file,
              fileName: file.name,
              width: dims.width || undefined,
              height: dims.height || undefined,
            },
          };
        }
        const probe = await probeVideo(url);
        const { duration } = probe;
        if (
          opts.maxVideoSeconds !== undefined &&
          duration !== undefined &&
          duration > opts.maxVideoSeconds
        ) {
          releaseVideo(probe.video);
          URL.revokeObjectURL(url);
          return {
            error: {
              kind: "video-too-long",
              message: opts.errors.videoTooLong({
                file,
                seconds: duration,
                maxSeconds: opts.maxVideoSeconds,
              }),
              file,
              durationSeconds: duration,
              maxSeconds: opts.maxVideoSeconds,
            },
          };
        }
        let posterBlob: Blob | undefined;
        if (posterAt !== false) {
          posterBlob = (await grabPoster(probe.video, posterAt, duration)) ?? undefined;
        }
        releaseVideo(probe.video);
        return {
          item: {
            id: nextId(),
            kind,
            url,
            blob: file,
            fileName: file.name,
            width: probe.width || undefined,
            height: probe.height || undefined,
            duration,
            posterBlob,
            posterUrl: posterBlob ? URL.createObjectURL(posterBlob) : undefined,
          },
        };
      },
    ),
  );

  const items: MediaCarouselItem[] = [];
  for (const b of built) {
    if ("item" in b) items.push(b.item);
    else errors.push(b.error);
  }
  return { items, errors };
}

interface Formatters {
  plain: Intl.NumberFormat;
  two: Intl.NumberFormat;
}

// Formatters are pure, so one pair per locale is shared by every call.
const cache = new Map<string, Formatters>();

function build(locale: string): Formatters {
  return {
    plain: new Intl.NumberFormat(locale, { useGrouping: false }),
    two: new Intl.NumberFormat(locale, {
      minimumIntegerDigits: 2,
      useGrouping: false,
    }),
  };
}

function formattersFor(locale: string): Formatters {
  const hit = cache.get(locale);
  if (hit) return hit;
  let made: Formatters;
  try {
    made = build(locale);
  } catch {
    // An invalid tag such as "tr_TR" throws a RangeError; read it as English.
    made = cache.get("en") ?? build("en");
    cache.set("en", made);
  }
  cache.set(locale, made);
  return made;
}

/**
 * `m:ss` (or `h:mm:ss` past an hour) with digits from `locale`.
 * Non-finite or negative input reads as zero.
 * An invalid `locale` reads as `"en"`.
 */
export function formatDuration(seconds: number, locale = "en"): string {
  const safe = Number.isFinite(seconds) && seconds > 0 ? Math.floor(seconds) : 0;
  const h = Math.floor(safe / 3600);
  const m = Math.floor((safe % 3600) / 60);
  const s = safe % 60;
  const { plain, two } = formattersFor(locale);
  return h > 0
    ? `${plain.format(h)}:${two.format(m)}:${two.format(s)}`
    : `${plain.format(m)}:${two.format(s)}`;
}

import {
  defaultCarouselComposerLabels,
  type CarouselComposerLabels,
  type CarouselComposerLabelsInput,
} from "../types";

/** Keys that were string templates in 0.2 and are functions now. */
const FUNCTION_KEYS = ["dropzoneHint", "maxReached", "itemAria"] as const;

export interface MergedLabels {
  labels: CarouselComposerLabels;
  /** Keys where a 0.2 string template was passed and ignored. */
  legacyKeys: string[];
}

/** A copy without the keys whose value is `undefined` (they must not hide a default). */
function definedOnly<T extends object>(input: T | undefined): Partial<T> {
  if (!input) return {};
  return Object.fromEntries(
    Object.entries(input).filter(([, v]) => v !== undefined),
  ) as Partial<T>;
}

/**
 * Merge `labels` over the English defaults; `errors` and `drag` merge key by key.
 * A string given for a key that is a function now is ignored (the default stays).
 */
export function mergeLabels(input?: CarouselComposerLabelsInput): MergedLabels {
  const defaults = defaultCarouselComposerLabels;
  if (!input) return { labels: defaults, legacyKeys: [] };
  const legacyKeys: string[] = [];
  const clean: Record<string, unknown> = definedOnly(input);
  for (const key of FUNCTION_KEYS) {
    if (typeof clean[key] === "string") {
      legacyKeys.push(key);
      delete clean[key];
    }
  }
  const { errors, drag, ...rest } = clean as CarouselComposerLabelsInput;
  const labels: CarouselComposerLabels = {
    ...defaults,
    ...(rest as Partial<CarouselComposerLabels>),
    errors: { ...defaults.errors, ...definedOnly(errors) },
    drag: { ...defaults.drag, ...definedOnly(drag) },
  };
  // 0.2 hosts translated `remove`; until they adopt `removeItem`, their text names the buttons.
  if (typeof rest.remove === "string" && rest.removeItem === undefined) {
    const text = rest.remove;
    labels.removeItem = () => text;
  }
  return { labels, legacyKeys };
}

/** Longest edge of a poster frame, in pixels. Keeps a 4K video within canvas limits. */
const POSTER_MAX_EDGE = 1280;

/** How long to wait for a video's metadata or a seek before giving up. */
const WAIT_MS = 8000;

export interface VideoProbe {
  width: number;
  height: number;
  /** Seconds; `undefined` when the browser cannot read it. */
  duration?: number;
  video: HTMLVideoElement;
}

/** Load a video's metadata. Resolves with zeros / no duration when it cannot be read. */
export function probeVideo(url: string): Promise<VideoProbe> {
  return new Promise((resolve) => {
    const video = document.createElement("video");
    video.preload = "metadata";
    video.muted = true;
    let done = false;
    const finish = (ok: boolean) => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      const d = video.duration;
      resolve({
        width: ok ? video.videoWidth : 0,
        height: ok ? video.videoHeight : 0,
        duration: ok && Number.isFinite(d) && d > 0 ? d : undefined,
        video,
      });
    };
    const timer = setTimeout(() => finish(false), WAIT_MS);
    video.onloadedmetadata = () => finish(true);
    video.onerror = () => finish(false);
    video.src = url;
  });
}

/** Drop the probe's media resources. */
export function releaseVideo(video: HTMLVideoElement): void {
  video.onloadedmetadata = null;
  video.onerror = null;
  video.removeAttribute("src");
  try {
    video.load();
  } catch {
    /* not supported — nothing to release */
  }
}

/**
 * Grab one JPEG frame from an already-probed video at `at` seconds (clamped to
 * the duration). Resolves `null` on any failure; a missing poster is never an error.
 */
export function grabPoster(
  video: HTMLVideoElement,
  at: number,
  duration?: number,
): Promise<Blob | null> {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (blob: Blob | null) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      video.removeEventListener("seeked", onSeeked);
      video.removeEventListener("error", onFail);
      resolve(blob);
    };
    const draw = () => {
      try {
        const w = video.videoWidth;
        const h = video.videoHeight;
        if (!w || !h) return finish(null);
        const scale = Math.min(1, POSTER_MAX_EDGE / Math.max(w, h));
        const cw = Math.max(1, Math.round(w * scale));
        const ch = Math.max(1, Math.round(h * scale));
        const canvas = document.createElement("canvas");
        canvas.width = cw;
        canvas.height = ch;
        const ctx = canvas.getContext("2d");
        if (!ctx) return finish(null);
        ctx.drawImage(video, 0, 0, cw, ch);
        canvas.toBlob((blob) => finish(blob), "image/jpeg", 0.85);
      } catch {
        finish(null);
      }
    };
    const onSeeked = () => draw();
    const onFail = () => finish(null);
    const timer = setTimeout(() => finish(null), WAIT_MS);
    video.addEventListener("seeked", onSeeked);
    video.addEventListener("error", onFail);
    try {
      const max = duration !== undefined ? Math.max(0, duration - 0.05) : at;
      let target = Math.max(0, Math.min(at, max));
      // A seek to the current time fires no "seeked"; nudge it.
      if (target === video.currentTime) target += 0.001;
      video.currentTime = target;
    } catch {
      finish(null);
    }
  });
}

import type {
  CarouselComposerErrorLabels,
  MediaCarouselError,
  MediaKind,
} from "../types";

export interface ValidateMediaOptions {
  maxFileSizeMb: number;
  /** Which kinds are accepted. */
  accept: MediaKind[];
  /** Exact MIME allow-list; when set the file's type must be in it. */
  acceptMime?: readonly string[];
  errors: CarouselComposerErrorLabels;
}

/**
 * Type + size check for one file: it must be an image or a video, in `accept`,
 * in `acceptMime` when that is set, and within the size cap. Messages come from
 * `errors`. The video length limit is checked later, once metadata is read.
 */
export function validateMediaFile(
  file: File,
  opts: ValidateMediaOptions,
): MediaCarouselError | null {
  const type = file.type;
  const isImage = type.startsWith("image/");
  const isVideo = type.startsWith("video/");
  const kind: MediaKind | null = isImage ? "image" : isVideo ? "video" : null;

  if (!kind) {
    return {
      kind: "unsupported-type",
      message: opts.errors.unsupportedType({ file, type }),
      file,
    };
  }
  if (
    opts.acceptMime &&
    !opts.acceptMime.some((m) => m.toLowerCase() === type.toLowerCase())
  ) {
    return {
      kind: "unsupported-type",
      message: opts.errors.unsupportedType({ file, type }),
      file,
    };
  }
  if (!opts.accept.includes(kind)) {
    return {
      kind: "unsupported-type",
      message: opts.errors.kindNotAccepted({ file, kind }),
      file,
    };
  }
  const maxBytes = opts.maxFileSizeMb * 1024 * 1024;
  if (file.size > maxBytes) {
    return {
      kind: "file-too-large",
      message: opts.errors.fileTooLarge({
        file,
        sizeMb: file.size / 1024 / 1024,
        maxMb: opts.maxFileSizeMb,
      }),
      file,
    };
  }
  return null;
}

