export interface AltFieldProps {
  /** The selected item; the parent decides whether it may be described (`enableAltText`). */
  item: MediaCarouselItem | null;
  maxLength: number;
  labels: Pick<CarouselComposerLabels, "altLabel" | "altPlaceholder" | "altPlaceholderVideo" | "altCounter">;
  onChange: (id: string, alt: string) => void;
}

/** Alt-text input for the selected item, with a visible counter. */
export function AltField({ item, maxLength, labels, onChange }: AltFieldProps) {
  const id = useId();
  const counterId = `${id}-counter`;
  if (!item) return null;
  const value = item.alt ?? "";
  return (
    <div className="flex flex-col gap-1">
      <label htmlFor={id} className="text-xs font-medium text-foreground">
        {labels.altLabel}
      </label>
      <Input
        id={id}
        value={value}
        maxLength={maxLength}
        aria-describedby={counterId}
        placeholder={
          item.kind === "video"
            ? (labels.altPlaceholderVideo ?? defaultCarouselComposerLabels.altPlaceholderVideo)
            : labels.altPlaceholder
        }
        onChange={(e) => onChange(item.id, e.target.value.slice(0, maxLength))}
      />
      <span id={counterId} className="self-end text-xs text-muted-foreground">
        {labels.altCounter(value.length, maxLength)}
      </span>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

export interface EditFrameProps {
  /** Accessible name of the region, e.g. `labels.edit`. */
  label: string;
  children: React.ReactNode;
}

/**
 * Wraps the injected edit panel. On mount it takes focus, unless the panel
 * already moved focus inside, so keyboard users land in the editor and not on
 * a button that has just left the page.
 */
export function EditFrame({ label, children }: EditFrameProps) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const el = ref.current;
    if (!el || el.contains(document.activeElement)) return;
    el.focus();
  }, []);
  return (
    <div ref={ref} role="group" aria-label={label} tabIndex={-1} className="outline-none">
      {children}
    </div>
  );
}

"use client";

import { AlertCircle, RotateCw } from "lucide-react";
import { Button } from "@/components/ui/button";
import type {
  CarouselComposerLabels,
  MediaCarouselItem,
} from "../types";
import { UploadProgress, clampProgress } from "./upload-progress";

export interface ItemStatusProps {
  item: MediaCarouselItem | null;
  labels: Pick<
    CarouselComposerLabels,
    "uploadProgress" | "uploadFailed" | "retry"
  >;
  /** 1-based position of the item and the item count, for the progress name. */
  position: number;
  total: number;
  onRetry?: (item: MediaCarouselItem) => void;
}

/**
 * Upload state of the selected item, under the preview: a determinate progress
 * bar while uploading, the error text with a Retry (when `onRetry` is wired) on
 * error. Nothing for `uploaded`, no status, or `pending` (the rail thumb carries
 * the pending mark).
 */
export function ItemStatus({ item, labels, position, total, onRetry }: ItemStatusProps) {
  if (!item) return null;
  if (item.status === "uploading") {
    return (
      <UploadProgress
        progress={item.progress}
        itemId={item.id}
        label={labels.uploadProgress(clampProgress(item.progress), { position, total })}
      />
    );
  }
  if (item.status === "error") {
    return (
      <div className="flex items-center gap-2 rounded-md border border-destructive/40 bg-destructive/10 px-3 py-2 text-sm text-foreground">
        <AlertCircle className="size-4 shrink-0 text-destructive" aria-hidden />
        <span className="min-w-0 flex-1">{item.error ?? labels.uploadFailed}</span>
        {onRetry ? (
          <Button
            type="button"
            size="sm"
            variant="outline"
            onClick={() => onRetry(item)}
          >
            <RotateCw className="size-3.5" aria-hidden />
            {labels.retry}
          </Button>
        ) : null}
      </div>
    );
  }
  return null;
}

"use client";

import { useRef, useState, type KeyboardEvent, type PointerEvent, type ReactNode } from "react";
import { ImageIcon, Pencil } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import type { CarouselCropOffset, MediaCarouselItem } from "../types";
import { clampOffset } from "../lib/aspect";

export interface MainPreviewProps {
  item: MediaCarouselItem | null;
  /** CSS `aspect-ratio` value for the frame (the shared carousel aspect). */
  aspectCss: string;
  /** True when the editing add-on is wired and this item may be edited. */
  canEdit: boolean;
  /** True when the editing add-on is wired. Without it the preview shows no edit UI. */
  editingEnabled?: boolean;
  labels: { edit: string; videoNotEditable: string };
  /** The aspect switch, shown over the top-start corner of the frame. */
  aspectSwitch?: ReactNode;
  onEdit: () => void;
  /** Shared aspect as width / height (`null` = free / none). Pan needs a fixed ratio. */
  ratio?: number | null;
  /** Pan (`enablePan`): the accessible name and the commit callback. Absent = no pan. */
  pan?: { label: string; onCommit: (id: string, offset: CarouselCropOffset) => void };
}

/** Arrow-key step of a pan (a fraction of the overflow); Shift takes the large one. */
const PAN_STEP = 0.05;
const PAN_STEP_LARGE = 0.2;

/** Frame size, displayed (cover-fitted) overflow of the image in CSS px. */
function overflowOf(frame: HTMLElement, w: number, h: number) {
  const r = frame.getBoundingClientRect();
  const scale = Math.max(r.width / w, r.height / h);
  // The fitted axis comes out as float noise (w * (r.width / w) - r.width ≈ 1e-14), not 0:
  // under half a pixel is "no overflow", so an arrow on that axis is ignored.
  const snap = (v: number) => (v < 0.5 ? 0 : v);
  return {
    x: snap(w * scale - r.width),
    y: snap(h * scale - r.height),
  };
}

/**
 * The large preview of the currently-selected item, with an Edit affordance.
 * Images fill the shared-aspect frame (`object-cover`); videos keep their own
 * aspect on a media-overlay mat (`object-contain`). A video is never editable — instead
 * of a disabled (unfocusable, unreadable) button we show a static caption that
 * IS in the reading order, so keyboard + screen-reader users get the reason.
 */
export function MainPreview({
  item,
  aspectCss,
  canEdit,
  editingEnabled = false,
  labels,
  aspectSwitch,
  onEdit,
  ratio = null,
  pan,
}: MainPreviewProps) {
  const frameRef = useRef<HTMLDivElement>(null);
  // Pending pan: the drag in progress, then (after pointerup / a key press) the offset we
  // committed, kept until the item's own `cropOffset` matches it — a controlled host that
  // echoes late must not see a snap-back. Bound to the image it was made for (id + size).
  const [live, setLive] = useState<{
    id: string;
    w: number;
    h: number;
    x: number;
    y: number;
  } | null>(null);
  const drag = useRef<{
    id: string;
    pointerId: number;
    startX: number;
    startY: number;
    from: CarouselCropOffset;
    last: CarouselCropOffset;
  } | null>(null);

  const imgW = item?.width ?? 0;
  const imgH = item?.height ?? 0;
  const pannable =
    pan !== undefined &&
    item !== null &&
    item.kind === "image" &&
    ratio !== null &&
    imgW > 0 &&
    imgH > 0 &&
    Math.abs(imgW / imgH - ratio) / ratio >= 0.002;

  const liveOffset: CarouselCropOffset | null =
    live && item && live.id === item.id && live.w === imgW && live.h === imgH
      ? { x: live.x, y: live.y }
      : null;
  // Drop a pending pan once it is stale (another item / a new size) or the host caught up.
  if (
    live &&
    (liveOffset === null ||
      (clampOffset(item?.cropOffset?.x) === live.x && clampOffset(item?.cropOffset?.y) === live.y))
  ) {
    setLive(null);
  }

  const current = (): CarouselCropOffset => ({
    x: clampOffset((liveOffset ?? item?.cropOffset)?.x),
    y: clampOffset((liveOffset ?? item?.cropOffset)?.y),
  });
  const pend = (id: string, o: CarouselCropOffset) =>
    setLive({ id, w: imgW, h: imgH, x: o.x, y: o.y });

  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    if (!pannable || !item || !pan) return;
    // A second pointer must not overwrite the drag in progress.
    if (drag.current) return;
    if (e.button !== 0 && e.pointerType === "mouse") return;
    // Overlay controls (aspect switch, Edit) keep their own clicks.
    if ((e.target as Element).closest("button, a, input, [role='radio'], [role='button']")) return;
    const from = current();
    drag.current = {
      id: item.id,
      pointerId: e.pointerId,
      startX: e.clientX,
      startY: e.clientY,
      from,
      last: from,
    };
    try {
      e.currentTarget.setPointerCapture?.(e.pointerId);
    } catch {
      /* capture unsupported — the drag still works inside the frame */
    }
  };

  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d || d.pointerId !== e.pointerId || !frameRef.current) return;
    const o = overflowOf(frameRef.current, imgW, imgH);
    // Dragging the photo right reveals more of its left: the focal point moves the other way.
    const next = {
      x: o.x > 0 ? clampOffset(d.from.x - (e.clientX - d.startX) / o.x) : d.from.x,
      y: o.y > 0 ? clampOffset(d.from.y - (e.clientY - d.startY) / o.y) : d.from.y,
    };
    d.last = next;
    pend(d.id, next);
  };

  const endDrag = (e: PointerEvent<HTMLDivElement>, commit: boolean) => {
    const d = drag.current;
    if (!d || d.pointerId !== e.pointerId) return;
    drag.current = null;
    try {
      e.currentTarget.releasePointerCapture?.(e.pointerId);
    } catch {
      /* already released */
    }
    if (commit && (d.last.x !== d.from.x || d.last.y !== d.from.y)) {
      // The pending offset stays (see `live`) until the committed value arrives.
      pan?.onCommit(d.id, d.last);
    } else {
      setLive(null);
    }
  };

  // Keyboard: each key commits (one onCropOffsetChange per press, no debounce). Arrow keys
  // move the VIEW WINDOW: Right / Down raise x / y. Physical axes (a photo does not mirror).
  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (!pannable || !item || !pan || e.target !== e.currentTarget) return;
    if (e.nativeEvent.isComposing || e.altKey || e.ctrlKey || e.metaKey) return;
    const step = e.shiftKey ? PAN_STEP_LARGE : PAN_STEP;
    const dx = e.key === "ArrowRight" ? step : e.key === "ArrowLeft" ? -step : 0;
    const dy = e.key === "ArrowDown" ? step : e.key === "ArrowUp" ? -step : 0;
    if (dx === 0 && dy === 0) return;
    const frame = frameRef.current;
    const o = frame ? overflowOf(frame, imgW, imgH) : { x: 1, y: 1 };
    const cur = current();
    const next = {
      x: dx !== 0 && o.x > 0 ? clampOffset(cur.x + dx) : cur.x,
      y: dy !== 0 && o.y > 0 ? clampOffset(cur.y + dy) : cur.y,
    };
    if ((dx !== 0 && o.x <= 0) || (dy !== 0 && o.y <= 0)) return;
    e.preventDefault();
    if (next.x !== cur.x || next.y !== cur.y) {
      // Step from the pending offset next time, even before the host echoes this one.
      pend(item.id, next);
      pan.onCommit(item.id, next);
    }
  };
  if (!item) {
    return (
      <div
        className="grid w-full place-items-center rounded-lg border border-dashed border-border bg-muted/30 text-muted-foreground"
        style={{ aspectRatio: aspectCss }}
      >
        <ImageIcon className="size-8" aria-hidden />
      </div>
    );
  }

  return (
    <div
      ref={frameRef}
      className={cn(
        "relative w-full overflow-hidden rounded-lg border border-border bg-muted",
        pannable &&
          // One overflow axis by construction: leave the OTHER axis to the browser, so a
          // phone can still scroll the page past the preview. Never `touch-none`.
          (imgW / imgH > (ratio as number) ? "touch-pan-y" : "touch-pan-x"),
        pannable &&
          "cursor-grab select-none outline-none focus-visible:ring-2 focus-visible:ring-ring active:cursor-grabbing",
      )}
      style={{ aspectRatio: aspectCss }}
      {...(pannable
        ? {
            role: "group",
            tabIndex: 0,
            "aria-label": pan?.label,
            "data-pan": "",
            onPointerDown,
            onPointerMove,
            onPointerUp: (e: PointerEvent<HTMLDivElement>) => endDrag(e, true),
            onPointerCancel: (e: PointerEvent<HTMLDivElement>) => endDrag(e, false),
            onLostPointerCapture: (e: PointerEvent<HTMLDivElement>) => endDrag(e, false),
            onKeyDown,
          }
        : {})}
    >
      {item.kind === "video" ? (
        <video
          src={item.url}
          controls
          playsInline
          preload="metadata"
          onLoadedMetadata={(e) => {
            try {
              e.currentTarget.currentTime = 0.1;
            } catch {
              /* seeking unsupported — leave as-is */
            }
          }}
          poster={item.posterUrl}
          aria-label={item.alt || undefined}
          className="size-full bg-media-overlay object-contain"
        />
      ) : (
        <img
          src={item.url}
          alt={item.alt ?? item.fileName ?? ""}
          draggable={pannable ? false : undefined}
          style={
            liveOffset || item.cropOffset
              ? {
                  objectPosition: `${current().x * 100}% ${current().y * 100}%`,
                }
              : undefined
          }
          className="size-full object-cover"
        />
      )}

      {aspectSwitch ? <div className="absolute start-3 top-3">{aspectSwitch}</div> : null}

      {canEdit ? (
        <div className="absolute end-3 top-3">
          <Button type="button" size="sm" onClick={onEdit} data-edit-button="">
            <Pencil className="size-4" aria-hidden />
            {labels.edit}
          </Button>
        </div>
      ) : editingEnabled && item.kind === "video" ? (
        <div className="absolute end-3 top-3">
          <span className="rounded-full bg-media-overlay px-2.5 py-1 text-xs font-medium text-media-overlay-foreground">
            {labels.videoNotEditable}
          </span>
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useRef, useState } from "react";
import { ImagePlus, Loader2, Plus } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import type { CarouselComposerLabels, MediaKind } from "../types";

export interface MediaDropzoneProps {
  variant: "empty" | "add-more";
  accept: MediaKind[];
  /** Exact MIME allow-list; becomes the input's `accept` when set. */
  acceptMime?: readonly string[];
  maxItems: number;
  disabled?: boolean;
  /** Ingestion in progress — show a spinner + block input. */
  busy?: boolean;
  labels: Pick<
    CarouselComposerLabels,
    | "dropzoneTitle"
    | "dropzoneBrowse"
    | "dropzoneHint"
    | "dropzoneBusy"
    | "addMore"
  >;
  onFiles: (files: File[] | FileList) => void;
}

function acceptAttr(
  accept: MediaKind[],
  acceptMime?: readonly string[],
): string {
  if (acceptMime && acceptMime.length > 0) {
    // Only the MIME types of an accepted kind; a type of a refused kind would be
    // selectable in the picker and then rejected.
    const inKinds = acceptMime.filter((m) =>
      accept.some((k) => m.toLowerCase().startsWith(`${k}/`)),
    );
    if (inKinds.length > 0) return inKinds.join(",");
  }
  return accept.map((k) => (k === "image" ? "image/*" : "video/*")).join(",");
}

/**
 * File intake surface. `variant="empty"` is the full-bleed first-run dropzone;
 * `variant="add-more"` is a compact rail-sized tile. Both wrap a hidden
 * `<input type="file" multiple>`, both accept drag-and-drop with hover feedback,
 * and both surface a `busy` spinner during ingestion. Drag-and-drop is an
 * enhancement on top of the always-present Browse button (keyboard path).
 */
export function MediaDropzone({
  variant,
  accept,
  acceptMime,
  maxItems,
  disabled,
  busy,
  labels,
  onFiles,
}: MediaDropzoneProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [dragging, setDragging] = useState(false);
  const blocked = disabled || busy;

  const open = () => inputRef.current?.click();

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    if (!blocked) setDragging(true);
  };
  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragging(false);
    if (blocked) return;
    if (e.dataTransfer.files?.length) onFiles(e.dataTransfer.files);
  };

  const onChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    // Snapshot into an array BEFORE resetting `value`: clearing a file input's
    // value empties its live `FileList` in place, so the captured reference
    // would otherwise reach `onFiles` already empty (silent no-add on browse).
    const files = e.target.files ? Array.from(e.target.files) : [];
    e.target.value = ""; // allow re-picking the same file
    if (files.length) onFiles(files);
  };

  const input = (
    <input
      ref={inputRef}
      type="file"
      multiple
      accept={acceptAttr(accept, acceptMime)}
      onChange={onChange}
      className="sr-only"
      tabIndex={-1}
      aria-hidden
    />
  );

  if (variant === "add-more") {
    return (
      <>
        <button
          type="button"
          onClick={open}
          onDragOver={onDragOver}
          onDragLeave={() => setDragging(false)}
          onDrop={onDrop}
          disabled={blocked}
          aria-label={labels.addMore}
          data-dropzone-add-more=""
          aria-busy={busy || undefined}
          className={cn(
            "grid size-16 shrink-0 place-items-center rounded-md border border-dashed bg-muted/40 text-muted-foreground transition hover:border-ring hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
            dragging
              ? "border-ring bg-accent/40 text-foreground"
              : "border-border",
          )}
        >
          {busy ? (
            <Loader2 className="size-5 animate-spin" aria-hidden />
          ) : (
            <Plus className="size-5" aria-hidden />
          )}
        </button>
        {input}
      </>
    );
  }

  return (
    <div
      role="group"
      onDragOver={onDragOver}
      onDragLeave={() => setDragging(false)}
      onDrop={onDrop}
      aria-label={labels.dropzoneTitle}
      aria-busy={busy || undefined}
      className={cn(
        "flex w-full flex-col items-center justify-center gap-3 rounded-lg border-2 border-dashed p-10 text-center transition",
        dragging ? "border-ring bg-accent/40" : "border-border bg-muted/30",
      )}
    >
      {busy ? (
        <Loader2
          className="size-8 animate-spin text-muted-foreground"
          aria-hidden
        />
      ) : (
        <ImagePlus className="size-8 text-muted-foreground" aria-hidden />
      )}
      <div className="flex flex-col gap-1">
        <p className="text-sm font-medium text-foreground">
          {busy ? labels.dropzoneBusy : labels.dropzoneTitle}
        </p>
        <p className="text-xs text-muted-foreground">
          {labels.dropzoneHint(maxItems)}
        </p>
      </div>
      <Button
        type="button"
        size="sm"
        onClick={open}
        disabled={blocked}
        data-dropzone-browse=""
      >
        {labels.dropzoneBrowse}
      </Button>
      {input}
    </div>
  );
}

"use client";

import {
  SortableContext,
  horizontalListSortingStrategy,
} from "@dnd-kit/sortable";
import { cn } from "@/lib/utils";
import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area";
import type {
  CarouselComposerLabels,
  MediaCarouselItem,
  MediaKind,
} from "../types";
import { MediaDropzone } from "./media-dropzone";
import { RailThumb } from "./rail-thumb";

export interface PreviewRailProps {
  items: MediaCarouselItem[];
  selectedId: string | null;
  /** Editing in progress → the whole rail is read-only. */
  disabled: boolean;
  canAddMore: boolean;
  /** Ingestion in progress — spinner on the add-more tile. */
  busy?: boolean;
  accept: MediaKind[];
  acceptMime?: readonly string[];
  maxItems: number;
  labels: Pick<
    CarouselComposerLabels,
    | "removeItem"
    | "reorderHint"
    | "itemAria"
    | "dropzoneTitle"
    | "dropzoneBrowse"
    | "dropzoneHint"
    | "dropzoneBusy"
    | "addMore"
    | "finishEditingHint"
    | "uploadProgress"
    | "uploadFailed"
    | "retry"
    | "durationLabel"
    | "moveEarlier"
    | "moveLater"
  >;
  formatDuration: (seconds: number) => string;
  /** Shared aspect as width / height (`null` = free). */
  ratio?: number | null;
  onRetry?: (item: MediaCarouselItem) => void;
  onSelect: (id: string) => void;
  onRemove: (id: string) => void;
  onFiles: (files: File[] | FileList) => void;
  reorderButtons?: boolean;
  onMove?: (id: string, delta: number) => void;
  /** Resolved text direction. Radix ScrollArea needs it explicitly. */
  dir?: "ltr" | "rtl";
}

/**
 * Horizontal thumbnail strip. `SortableContext` (horizontal strategy) drives
 * reorder; the wrapping `DndContext` lives in the root component. A trailing
 * compact dropzone tile adds more items when under `maxItems` and not editing.
 */
export function PreviewRail({
  items,
  selectedId,
  disabled,
  canAddMore,
  busy,
  accept,
  acceptMime,
  maxItems,
  labels,
  formatDuration,
  ratio,
  onRetry,
  onSelect,
  onRemove,
  onFiles,
  reorderButtons,
  onMove,
  dir,
}: PreviewRailProps) {
  return (
    <ScrollArea className="w-full" dir={dir}>
      {disabled ? (
        <p className="px-1 pb-1 text-xs text-muted-foreground">
          {labels.finishEditingHint}
        </p>
      ) : null}
      <div
        dir={dir}
        className={cn(
          "flex items-center gap-2 p-1 transition-opacity",
          disabled && "pointer-events-none opacity-60",
        )}
      >
        <SortableContext
          items={items.map((it) => it.id)}
          strategy={horizontalListSortingStrategy}
        >
          {items.map((item, i) => (
            <RailThumb
              key={item.id}
              item={item}
              index={i}
              total={items.length}
              selected={item.id === selectedId}
              disabled={disabled}
              labels={labels}
              formatDuration={formatDuration}
              ratio={ratio}
              onSelect={onSelect}
              onRemove={onRemove}
              onRetry={onRetry}
              reorderButtons={reorderButtons}
              onMove={onMove}
            />
          ))}
        </SortableContext>
        {canAddMore && !disabled ? (
          <MediaDropzone
            variant="add-more"
            accept={accept}
            acceptMime={acceptMime}
            maxItems={maxItems}
            busy={busy}
            labels={labels}
            onFiles={onFiles}
          />
        ) : null}
      </div>
      <ScrollBar orientation="horizontal" />
    </ScrollArea>
  );
}

"use client";

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { AlertCircle, ChevronLeft, ChevronRight, Clock, Film, GripVertical, RotateCw, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { defaultCarouselComposerLabels } from "../types";
import type { CarouselComposerLabels, MediaCarouselItem } from "../types";
import { clampOffset, thumbHeightRem, thumbWidthRem } from "../lib/aspect";
import { UploadProgress, clampProgress } from "./upload-progress";

export interface RailThumbProps {
  item: MediaCarouselItem;
  index: number;
  total: number;
  selected: boolean;
  /** Editing in progress → rail is read-only (no drag, remove, or re-select). */
  disabled: boolean;
  labels: Pick<
    CarouselComposerLabels,
    | "removeItem"
    | "reorderHint"
    | "itemAria"
    | "uploadProgress"
    | "uploadFailed"
    | "retry"
    | "durationLabel"
    | "moveEarlier"
    | "moveLater"
  >;
  /** Shared aspect as width / height (`null` = free, square). The thumb keeps its height. */
  ratio?: number | null;
  /** Formats the duration badge of a video. */
  formatDuration: (seconds: number) => string;
  onSelect: (id: string) => void;
  onRemove: (id: string) => void;
  /** Shows a Retry on an errored thumb (the selected item's Retry is under the preview). */
  onRetry?: (item: MediaCarouselItem) => void;
  /** `reorderButtons`: render the move earlier / later pair. */
  reorderButtons?: boolean;
  /** One-step move; `delta` is -1 (earlier) or 1 (later). */
  onMove?: (id: string, delta: number) => void;
}

/**
 * A single rail thumbnail. The body is a native `<button>` for select (clean
 * Enter/Space keyboard activation). The drag `listeners` live on a SEPARATE
 * handle button so the `@dnd-kit` keyboard sensor never fights the select
 * button's native activation. Remove is a third button with `stopPropagation`.
 * Upload status (`uploading` / `pending` / `error`) shows on the thumb; for the
 * selected item the accessible progress and Retry live under the preview instead.
 */
export function RailThumb({
  item,
  index,
  total,
  selected,
  disabled,
  labels,
  ratio = 1,
  formatDuration,
  onSelect,
  onRemove,
  onRetry,
  reorderButtons = false,
  onMove,
}: RailThumbProps) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
    useSortable({ id: item.id, disabled });

  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  const aria = labels.itemAria({
    position: index + 1,
    total,
    kind: item.kind,
    alt: item.alt,
    status: item.status,
  });
  const progress = clampProgress(item.progress);
  const errorText = item.error ?? labels.uploadFailed;

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={cn("group relative shrink-0", isDragging && "z-10 opacity-60")}
    >
      <button
        type="button"
        aria-label={aria}
        data-thumb-select={item.id}
        aria-current={selected ? "true" : undefined}
        onClick={() => !disabled && onSelect(item.id)}
        disabled={disabled}
        style={{ width: `${thumbWidthRem(ratio)}rem`, height: `${thumbHeightRem(ratio)}rem` }}
        className={cn(
          "relative block overflow-hidden rounded-md border bg-muted outline-none transition focus-visible:ring-2 focus-visible:ring-ring",
          selected ? "border-ring ring-2 ring-ring" : "border-border",
          item.status === "pending" && "opacity-70",
        )}
      >
        {item.kind === "video" ? (
          <>
            {item.posterUrl ? (
              <img src={item.posterUrl} alt="" className="size-full object-cover" />
            ) : (
              <video
                src={item.url}
                muted
                playsInline
                preload="metadata"
                onLoadedMetadata={(e) => {
                  // Nudge to a frame so the thumb isn't a black box (Safari/Chrome
                  // won't paint frame 0 of an unplayed inline video otherwise).
                  try {
                    e.currentTarget.currentTime = 0.1;
                  } catch {
                    /* seeking unsupported — leave as-is */
                  }
                }}
                className="size-full object-cover"
              />
            )}
            {item.duration === undefined ? (
              <span className="absolute bottom-0.5 end-0.5 grid place-items-center rounded-sm bg-media-overlay p-0.5 text-media-overlay-foreground">
                <Film className="size-3" aria-hidden />
              </span>
            ) : null}
          </>
        ) : (
          <img
            src={item.url}
            alt={item.alt ?? item.fileName ?? ""}
            style={
              item.cropOffset
                ? {
                    objectPosition: `${clampOffset(item.cropOffset.x) * 100}% ${clampOffset(item.cropOffset.y) * 100}%`,
                  }
                : undefined
            }
            className="size-full object-cover"
          />
        )}
      </button>

      {item.kind === "video" && item.duration !== undefined ? (
        <span
          role="img"
          aria-label={labels.durationLabel(formatDuration(item.duration))}
          className="pointer-events-none absolute bottom-0.5 end-0.5 rounded-sm bg-media-overlay px-1 text-[10px] font-medium leading-4 text-media-overlay-foreground tabular-nums"
        >
          {formatDuration(item.duration)}
        </span>
      ) : null}

      {item.status === "uploading" ? (
        <div className="pointer-events-none absolute inset-x-1 top-1">
          <UploadProgress
            progress={progress}
            itemId={item.id}
            label={labels.uploadProgress(progress, { position: index + 1, total })}
            decorative={selected}
            className="h-1"
          />
        </div>
      ) : null}

      {item.status === "pending" ? (
        <span className="pointer-events-none absolute start-1 top-1 grid place-items-center rounded-sm bg-media-overlay p-0.5 text-media-overlay-foreground">
          <Clock className="size-3" aria-hidden />
        </span>
      ) : null}

      {item.status === "error" ? (
        <div className="pointer-events-none absolute inset-0 grid place-items-start rounded-md bg-destructive/60 p-1">
          <AlertCircle
            role={selected ? undefined : "img"}
            aria-label={selected ? undefined : errorText}
            aria-hidden={selected ? true : undefined}
            className="size-4 text-destructive-foreground"
          />
        </div>
      ) : null}

      {item.status === "error" && onRetry && !selected && !disabled ? (
        <button
          type="button"
          aria-label={labels.retry}
          onClick={(e) => {
            e.stopPropagation();
            onRetry(item);
          }}
          className="absolute inset-0 m-auto grid size-6 place-items-center rounded-full bg-destructive text-destructive-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          <RotateCw className="size-3.5" aria-hidden />
        </button>
      ) : null}

      {!disabled ? (
        <>
          <button
            type="button"
            aria-label={labels.reorderHint}
            {...attributes}
            {...listeners}
            className="absolute bottom-0.5 start-0.5 grid size-6 cursor-grab touch-none place-items-center rounded bg-media-overlay text-media-overlay-foreground opacity-90 transition hover:opacity-100 focus-visible:opacity-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring active:cursor-grabbing"
          >
            <GripVertical className="size-4" aria-hidden />
          </button>
          {reorderButtons ? (
            <div
              data-thumb-move-pair=""
              className={cn(
                "pointer-events-none absolute flex opacity-0 transition-opacity",
                "group-hover:pointer-events-auto group-hover:opacity-100 focus-within:pointer-events-auto focus-within:opacity-100",
                // Geometry (rem = 16px). Remove is size-6 at -top-1.5 / -end-1.5, so it covers
                // y -6..18 of the thumb; the grip is size-6 at bottom-0.5 / start-0.5, so it
                // covers y (H-26)..(H-2). A narrow thumb (9:16 = 36 px wide, 64 px tall) has no
                // room beside either, so the pair sits in the 20 px band between them
                // (top-5 .. 36 px; two size-4 buttons = 32 px wide, centred, no wider than themselves). A wider thumb (>= 5 rem)
                // has room on the bottom row right of the grip (start-[1.875rem]).
                thumbWidthRem(ratio) >= 5
                  ? "bottom-0.5 start-[1.875rem] gap-0.5"
                  : "inset-x-0 top-5 mx-auto w-fit",
              )}
            >
              {(["earlier", "later"] as const).map((which) => {
                const delta = which === "earlier" ? -1 : 1;
                const atEnd = which === "earlier" ? index === 0 : index === total - 1;
                const name = (
                  (which === "earlier" ? labels.moveEarlier : labels.moveLater) ??
                  (which === "earlier"
                    ? defaultCarouselComposerLabels.moveEarlier
                    : defaultCarouselComposerLabels.moveLater)!
                )({ position: index + 1, total });
                const Icon = which === "earlier" ? ChevronLeft : ChevronRight;
                return (
                  <button
                    key={which}
                    type="button"
                    aria-label={name}
                    // Not `disabled`: a focused button that disables itself drops focus to <body>.
                    aria-disabled={atEnd || undefined}
                    data-thumb-move={which}
                    data-thumb-id={item.id}
                    onClick={(e) => {
                      e.stopPropagation();
                      if (!atEnd) onMove?.(item.id, delta);
                    }}
                    className={cn(
                      "grid place-items-center rounded bg-media-overlay text-media-overlay-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring aria-disabled:opacity-50",
                      thumbWidthRem(ratio) >= 5 ? "size-5" : "size-4",
                    )}
                  >
                    <Icon className="size-3 rtl:rotate-180" aria-hidden />
                  </button>
                );
              })}
            </div>
          ) : null}
          <button
            type="button"
            aria-label={labels.removeItem({ position: index + 1, total, kind: item.kind })}
            onClick={(e) => {
              e.stopPropagation();
              onRemove(item.id);
            }}
            className="absolute -end-1.5 -top-1.5 grid size-6 place-items-center rounded-full border border-border bg-background text-foreground shadow-sm transition hover:bg-destructive hover:text-destructive-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <X className="size-3.5" aria-hidden />
          </button>
        </>
      ) : null}
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";

export interface UploadProgressProps {
  /** 0 to 1. Clamped; a missing or non-finite value reads as 0. */
  progress: number | undefined;
  /** Accessible name, e.g. `labels.uploadProgress(progress)`. */
  label: string;
  /** Visual only (no role) — used where the same state is exposed elsewhere. */
  decorative?: boolean;
  /** The item this bar belongs to; lets focus hand-off find it. */
  itemId?: string;
  className?: string;
}

/** Clamp to 0..1; NaN, Infinity and a missing value read as 0. */
export function clampProgress(progress: number | undefined): number {
  if (progress === undefined || !Number.isFinite(progress)) return 0;
  return Math.min(1, Math.max(0, progress));
}

/** A determinate progress bar. Without a number it shows an empty track. */
export function UploadProgress({
  progress,
  label,
  decorative,
  itemId,
  className,
}: UploadProgressProps) {
  const clamped = clampProgress(progress);
  const percent = Math.round(clamped * 100);
  const a11y = decorative
    ? ({ "aria-hidden": true } as const)
    : ({
        role: "progressbar",
        "aria-valuemin": 0,
        "aria-valuemax": 100,
        "aria-valuenow": percent,
        "aria-label": label,
        tabIndex: -1,
        "data-progress-for": itemId,
      } as const);
  return (
    <div
      {...a11y}
      className={cn(
        "h-1.5 w-full overflow-hidden rounded-full bg-media-overlay",
        className,
      )}
    >
      <div
        className="h-full rounded-full bg-primary transition-[width]"
        style={{ width: `${percent}%` }}
      />
    </div>
  );
}
